-- Completa campos vazios (UF, comarca, tribunal, vara, parte contraria,
-- valor da causa) a partir da planilha de provisao/contingencia que a
-- Souza Cruz mandou (exportacao do E-law dela, sheet Contingencia).
--
-- So preenche o que estiver vazio (COALESCE(atual, planilha)) -- nao
-- sobrescreve nada ja preenchido/curado pela equipe. "N/I" e vazio na
-- planilha viram NULL, nao sao gravados como texto.

DO $$
DECLARE
  _atualizados int;
BEGIN
  CREATE TEMP TABLE _provisao_souzacruz (
    cnj_digits text,
    uf text,
    comarca text,
    tribunal text,
    vara text,
    parte_contraria text,
    valor_causa numeric
  ) ON COMMIT DROP;


  UPDATE public.processos p
  SET uf = COALESCE(NULLIF(trim(p.uf), ''), d.uf),
      comarca = COALESCE(NULLIF(trim(p.comarca), ''), d.comarca),
      tribunal = COALESCE(NULLIF(trim(p.tribunal), ''), d.tribunal),
      vara = COALESCE(NULLIF(trim(p.vara), ''), d.vara),
      parte_contraria = COALESCE(NULLIF(trim(p.parte_contraria), ''), d.parte_contraria),
      valor_causa = COALESCE(p.valor_causa, d.valor_causa)
  FROM _provisao_souzacruz d
  WHERE regexp_replace(p.numero_cnj, '\D', '', 'g') = d.cnj_digits;

  GET DIAGNOSTICS _atualizados = ROW_COUNT;
  RAISE NOTICE 'Processos atualizados: %', _atualizados;
END $$;
